examples.code:
// After a scripted goal by the player's team: team 1 kicks off, the team
// gets a new tactic, and para_cp0008 learns the Special Move whs0003.
CMND_BTL_SET_MATCH_RESTART(1);
CMND_BTL_LEARNING_TACTICS(0, "wht0002");
CMND_BTL_LEARNING_SKILL(0, "para_cp0008", "whs0003", 0);

// Called by the engine when the match starts
CallMatchBeginMatch <- function ()
{
	// The opponent's para_cp0010 gets the Special Move whs0004
	CMND_BTL_LEARNING_SKILL(1, "para_cp0010", "whs0004", 0);
	// ...
};

// Skip it if global flag 2000 is already set
if (!CMND_GET_GLOBAL_BIT_FLAG(2000))
{
	CMND_BTL_LEARNING_SKILL(0, "para_cp0010", "whs0035", 0);
}
